import re as _re

def _money_bounds(label: str):
    """Извлекает коммерческий диапазон из строк вида 35–80 тыс. ₽.
    Для составной 1С-цены берём общий безопасный коридор 50–300 тыс.
    Пакеты без денежной цены оставляем None, чтобы не выдумывать стоимость.
    """
    text=(label or '').replace('\u00a0',' ')
    ranges=[]
    for m in _re.finditer(r'(\d[\d ]*)\s*[–—-]\s*(\d[\d ]*)\s*\+?\s*тыс', text, _re.I):
        lo=int(m.group(1).replace(' ',''))*1000
        hi=int(m.group(2).replace(' ',''))*1000
        ranges.append((lo,hi))
    if ranges:
        return min(x[0] for x in ranges), max(x[1] for x in ranges)
    singles=[]
    for m in _re.finditer(r'(\d[\d ]*)\s*\+?\s*тыс', text, _re.I):
        singles.append(int(m.group(1).replace(' ',''))*1000)
    if singles:
        return min(singles), max(singles)
    return None, None

for _svc in SERVICE_CATALOG:
    _lo,_hi=_money_bounds(_svc.get('price',''))
    _svc.setdefault('price_min_rub',_lo)
    _svc.setdefault('price_max_rub',_hi)
    _svc.setdefault('currency','RUB')
